namespace {
float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
}
std::optional<unsigned> ScriptSession::groundAttackWeapon(const UnitState& source){
    if(source.ethereal() || source.morphed() || source.spinning())return {};for(unsigned slot=0;slot<2;++slot){if(!weaponEnabled(source,slot))continue;auto weapon=unitWeapon(source,slot);if((weapon.kind=="artillery" || weapon.kind=="aline") && !source.attackPrevented(true))return slot;}return {};
}
bool ScriptSession::attackGround(std::uint32_t id,WorldPoint point){
    if(!alive(id,NativeKind::Unit) || !std::isfinite(number(point.x)) || !std::isfinite(number(point.y)))return false;auto unit=units_.at(id);if(unit->paused || unit->stunned() || unit->construction || unit->unsummon || unit->hidden() || unit->removing || number(unit->life)<=0)return false;auto slot=groundAttackWeapon(*unit);if(!slot)return false;point=requireWorld().clamp(point);auto weapon=unitWeapon(*unit,*slot);float distance=std::hypot(number(point.x)-number(unit->x),number(point.y)-number(unit->y)),range=weapon.range+unit->collision;if(distance<=range && distance>=weapon.minimumRange){unit->route.clear();unit->waypoint=0;}else if(unit->stationaryBuilding() || !chase(*unit,point,std::max(0.f,range-8)))return false;if(!cancelCombat(*unit) || !groundAttackWeapon(*unit))return false;unit->combat.attackGround=point;unit->combat.repath=simulationTime_+.25;unit->currentOrder=851984;unit->holding=false;ScriptContext context;context.issuedOrder=851984;context.orderPoint=point;unitEvent(id,39,76,context);return true;
}
void ScriptSession::combatAttackGround(std::uint32_t id,double delta){
    if(!alive(id,NativeKind::Unit))return;auto unit=units_.at(id);auto& order=unit->combat;if(!order.attackGround)return;auto point=*order.attackGround;auto slot=groundAttackWeapon(*unit);if(!slot){order.attackGround.reset();order.windup.reset();++order.revision;unit->route.clear();unit->waypoint=0;unit->currentOrder=0;return;}auto weapon=unitWeapon(*unit,*slot);float distance=std::hypot(number(point.x)-number(unit->x),number(point.y)-number(unit->y)),range=weapon.range+unit->collision;if(order.windup){if(simulationTime_>=order.windup->due){auto windup=*order.windup;order.windup.reset();if(windup.revision==order.revision && distance<=range+weapon.rangeBuffer)launchGroundAttack(id,point,windup.weapon);}return;}if(distance>range || distance<weapon.minimumRange){if(!unit->holding && !unit->stationaryBuilding() && simulationTime_>=order.repath){if(distance<weapon.minimumRange){float radius=weapon.minimumRange+unit->collision+16;float dx=distance>.001f?(number(unit->x)-number(point.x))/distance:1.f,dy=distance>.001f?(number(unit->y)-number(point.y))/distance:0.f;WorldPoint away{real(number(point.x)+dx*radius),real(number(point.y)+dy*radius)};chase(*unit,away,0);}else chase(*unit,point,std::max(0.f,range-8));order.repath=simulationTime_+.25;}return;}unit->route.clear();unit->waypoint=0;if(!unit->stationaryBuilding()){float heading=std::fmod(std::atan2(number(point.y)-number(unit->y),number(point.x)-number(unit->x))*180.f/3.14159265359f+360.f,360.f);if(turnUnit(*unit,heading,delta)>.2f)return;}if(simulationTime_<order.nextAttack)return;float speed=1+unit->technology.attackSpeed+unit->equipment.attackSpeed+unit->aura.attackSpeed+unit->spellBonus(&UnitBuff::attackBonus)-unit->spellAttackReduction();if(unit->hero && (!unit->illusion || gameplayNumber("IllusionsGetAttackSpeedBonus",1)!=0))speed+=unit->appliedHeroStats[1]*gameplayNumber("AgiAttackSpeedBonus",.02f);speed=std::clamp(speed,.2f,5.f);order.animationSpeed=speed;order.nextAttack=simulationTime_+std::max(1./32,double(weapon.cooldown/speed));order.animationEnd=simulationTime_+(weapon.point+weapon.backswing)/speed;order.windup=AttackWindup{0,*slot,simulationTime_+weapon.point/speed,order.revision};unit->animation="Attack";unit->animationIndex.reset();unit->animationQueue.clear();unit->animationTime=0;++unit->animationGeneration;
}
void ScriptSession::launchGroundAttack(std::uint32_t id,WorldPoint point,unsigned slot){
    if(!alive(id,NativeKind::Unit))return;auto unit=units_.at(id);auto selected=groundAttackWeapon(*unit);if(!selected || *selected!=slot || !unit->combat.attackGround)return;auto weapon=unitWeapon(*unit,slot);float damage=weapon.base;for(unsigned i=0;i<weapon.dice;++i)damage+=float(random()%weapon.sides+1);if(unit->hero){auto primary=definitions().field(unit->type,"UnitBalance","Primary");unsigned attribute=primary=="STR"?0:primary=="AGI"?1:2;damage+=unit->appliedHeroStats[attribute];}CombatProjectile shot;shot.definition=weapon;shot.definition.homing=false;shot.source=id;shot.sourceType=unit->type;shot.owner=unit->owner;shot.weapon=slot;shot.damage=attackDamageBeforeProc(*unit,weapon,damage);prepareSiegeAttack(*unit,shot);weapon=shot.definition;float angle=number(unit->facing)*3.14159265359f/180;shot.start={real(number(unit->x)+std::cos(angle)*weapon.launchX-std::sin(angle)*weapon.launchY),real(number(unit->y)+std::sin(angle)*weapon.launchX+std::cos(angle)*weapon.launchY)};shot.position=shot.start;shot.endpoint=point;shot.startMovement=pathMovement(unit->movementType);shot.endMovement=PathMovement::Ground;shot.startHeight=unit->displayFlyHeight()+weapon.launchZ;shot.endHeight=0;shot.distance=std::hypot(number(shot.start.x)-number(point.x),number(shot.start.y)-number(point.y));shot.born=simulationTime_;if(weapon.speed<=0)throw std::runtime_error("Ground attack requires source missile speed: "+ObjectData::name(unit->type));if(projectiles_.size()>=8192)throw std::runtime_error("Live projectile budget exceeded");shot.id=++projectileId_;projectiles_.emplace(shot.id,std::move(shot));
}
